const groupList = filter => Object.values(groups()).filter(filter).sort((a, b) => (b.status === 'Pending') - (a.status === 'Pending') || b.last - a.last);

// ════════ 4. API (satu pintu: fetch → Google Apps Script REST API) ════════
const Net = { pending: 0, online: true, lastOk: 0 };
const API_TIMEOUT_MS = 120000;
const GAS_URL_RE = /^https:\/\/script\.google\.com\/(?:a\/macros\/[^/]+|macros)\/s\/[\w-]+\/exec$/;
function apiUrl() { return String((window.ROVELO_CONFIG && window.ROVELO_CONFIG.GAS_URL) || '').trim(); }
function apiUrlValid() { return GAS_URL_RE.test(apiUrl()); }

/**
 * Kirim permintaan ke GAS. Content-Type text/plain → "simple request" (tanpa preflight CORS,
 * yang tidak didukung Apps Script). Token sesi hanya di body, tidak pernah di URL.
 */
async function gasFetch(url, opts) {
  const ctl = typeof AbortController === 'function' ? new AbortController() : null;
  const timer = ctl ? setTimeout(() => ctl.abort(), API_TIMEOUT_MS) : 0;
  try {
    const res = await fetch(url, Object.assign({ redirect: 'follow', cache: 'no-store', credentials: 'omit', signal: ctl ? ctl.signal : undefined }, opts));
    const text = await res.text();
    try { return JSON.parse(text); }
    catch (e) {
      console.warn('Respons API bukan JSON (HTTP ' + res.status + '):', text.slice(0, 300));
      return { success: false, code: 'SERVER', message: res.status === 404 ? 'Alamat API tidak ditemukan. Periksa GAS_URL di js/config.js.' : 'Server mengirim respons yang tidak dikenali. Pastikan deployment Apps Script diatur "Who has access: Anyone" dan versi terbaru sudah di-deploy.' };
    }
  } finally { clearTimeout(timer); }
}
function callApi(action, data) {
  return new Promise(resolve => {
    Net.pending++; renderSync();
    let settled = false;
    const done = res => {
      if (settled) return; settled = true;
      Net.pending = Math.max(0, Net.pending - 1);
      handleRes(res);
      renderSync();
      resolve(res);
    };
    gasFetch(apiUrl(), { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify({ action: action, token: S.token || '', data: data || {} }) })
      .then(res => done(res && typeof res === 'object' ? res : { success: false, code: 'EMPTY', message: 'Server tidak mengirim respons. Coba lagi.' }))
      .catch(err => { console.warn('API ' + action + ' gagal:', err); done({ success: false, code: 'NETWORK', message: netMsg(err) }); });
  });
}
/** Info publik (nama bisnis, logo, status database) — GET tanpa token. */
async function loadPublic() {
  const u = apiUrl();
  const res = await gasFetch(u + (u.indexOf('?') >= 0 ? '&' : '?') + 'action=app.publicInfo', { method: 'GET' });
  if (!res || !res.success) throw new Error((res && res.message) || 'Info publik tidak tersedia.');
  return res.data;
}
function netMsg(err) {
  const m = String(err && err.message ? err.message : err || '');
  if (err && err.name === 'AbortError') return 'Server terlalu lama merespons. Cek riwayat transaksi sebelum mengulang agar tidak tercatat dua kali.';
  if (typeof navigator !== 'undefined' && navigator.onLine === false) return 'Koneksi terputus. Transaksi tetap Pending — silakan coba lagi.';
  if (/failed to fetch|network|load failed|fetch|disconnect|timeout|-1/i.test(m)) return 'Gagal terhubung ke server. Periksa koneksi internet lalu coba lagi.';
  if (/quota|too many/i.test(m)) return 'Sistem sedang sibuk, coba beberapa menit lagi. Data Anda tidak hilang.';
  return m || 'Terjadi kesalahan tak terduga.';
}
function handleRes(res) {
  Net.online = res.code !== 'NETWORK';
  if (Net.online) Net.lastOk = Date.now();
  if (res.token) { S.token = res.token; store.set('rovelo_token', res.token); }
  if (res.code === 'AUTH' && S.token) { setTimeout(() => forceLogout(res.message), 0); return; }
  if (res.prevVer && S.ver && res.prevVer !== S.ver) scheduleRefresh();
  if (res.ver) S.ver = res.ver;
}
function renderSync() {
  const el = $('#sync');
  if (!el) return;
  el.classList.toggle('busy', Net.pending > 0);
  el.classList.toggle('off', !Net.online && !Net.pending);
  $('.txt', el).textContent = Net.pending > 0 ? 'Menyimpan…' : (!Net.online ? 'Offline' : 'Tersinkron');
}

/** Salin koleksi yang bisa berubah → dipakai untuk membatalkan UI optimistis. */
function snapshot() {
  return { stock: Object.assign({}, S.stock), tx: S.tx.map(t => Object.assign({}, t)), rts: S.rts.map(r => Object.assign({}, r)), po: clone(S.po), poItems: clone(S.poItems), opname: clone(S.opname), imports: clone(S.imports), dashboard: S.dashboard ? clone(S.dashboard) : null, variants: clone(S.variants), settings: Object.assign({}, S.settings) };
}
function restore(s) { Object.assign(S, s); reindex(); }
/** Gabungkan patch dari server (stok & baris transaksi otoritatif). */
function applyPatch(p, tmpTag) {
  if (!p) return;
  if (tmpTag) S.tx = S.tx.filter(t => t._tmp !== tmpTag);
  if (p.stock) Object.assign(S.stock, p.stock);
  if (p.tx && p.tx.length) {
    const byId = {}; S.tx.forEach((t, i) => { byId[t.TxID] = i; });
    p.tx.forEach(r => { const o = {}; S.txCols.forEach((k, i) => { o[k] = r[i]; }); if (byId[o.TxID] !== undefined) S.tx[byId[o.TxID]] = o; else S.tx.push(o); });
  }
  if (p.rts) upsert(S.rts, p.rts, 'RTSID');
  if (p.po) upsert(S.po, [].concat(p.po), 'PONumber');
  if (p.poItems) { const nos = {}; [].concat(p.poItems).forEach(i => { nos[i.PONumber] = 1; }); S.poItems = S.poItems.filter(i => !nos[i.PONumber]).concat(p.poItems); }
  if (p.opname) S.opname = p.opname;
  txChanged();
}
function upsert(arr, items, key) { items.forEach(it => { const i = arr.findIndex(x => x[key] === it[key]); if (i >= 0) arr[i] = it; else arr.push(it); }); }

/** Terapkan konfirmasi di memori (stok & status) — sebelum server menjawab. */
function applyConfirmLocal(rows) {
  rows.forEach(r => {
    const before = stockOf(r.VariantID);
    r.StokSebelum = before; r.StokSesudah = before + r.Jumlah; S.stock[r.VariantID] = before + r.Jumlah;
    r.Status = 'Confirmed'; r.DikonfirmasiOleh = S.me.id; r.DikonfirmasiPada = now();
    const t = S.stockTotals[r.VariantID] || (S.stockTotals[r.VariantID] = [0, 0]);
    if (r.Jumlah > 0) t[0] += r.Jumlah; else t[1] -= r.Jumlah;
  });
  bumpDashLocal(rows);
  txChanged();
}
function bumpDashLocal(rows) {
  const d = S.dashboard;
  if (!d) return;
  const mk = monthKey(now());
  rows.forEach(r => {
    if (monthKey(r.Tanggal) !== mk) return;
    if (r.Jenis === 'IN' || r.Jenis === 'PO_IN') d.kpi.inMonth += r.Jumlah;
    if (r.Jenis === 'OUT' || r.Jenis === 'BUNDLE_OUT') {
      d.kpi.outMonth -= r.Jumlah;
      d.channels[r.Sumber] = (d.channels[r.Sumber] || 0) - r.Jumlah;
      const last = d.daily[d.daily.length - 1];
      if (last && dayIdx(last[0]) === dayIdx(r.Tanggal)) last[1] -= r.Jumlah;
    }
  });
  scheduleDash();
}
/** Pola UI optimistis: terapkan lokal → kirim → jika gagal, kembalikan. */
async function optimistic(o) {
  const snap = snapshot();
  if (o.apply) o.apply();
  afterChange();
  const res = await callApi(o.action, o.data);
  if (!res.success) {
    restore(snap); afterChange();
    if (o.onFail) o.onFail(res); else toast(o.errTitle || 'Tidak berhasil', res.message, 'danger', 8000);
    return res;
  }
  if (o.onOk) o.onOk(res.data || {}, res);
  afterChange();
  if (o.okTitle) toast(o.okTitle, o.okMsg || res.message, 'success');
  cacheStateSoon();
  return res;
}
function afterChange() { txChanged(); renderShell(); rerender(); }

// ── Sinkronisasi latar ──
let _refreshTimer = null, _dashTimer = null;
function scheduleRefresh() { clearTimeout(_refreshTimer); _refreshTimer = setTimeout(() => refresh(true), 800); }
function scheduleDash() {
  clearTimeout(_dashTimer);
  _dashTimer = setTimeout(async () => { const r = await callApi('app.dashboard'); if (r.success) { S.dashboard = r.data; if (UI.page === 'dashboard') rerender(); } }, 2500);
}
async function refresh(silent) {
  const before = S.tx.length;
  const res = await callApi('app.bootstrap');
  if (!res.success) {
    if (!silent && res.code !== 'AUTH') showBootError(res.message);
    return false;
  }
  applyBoot(res.data);
  cacheState(res.data);
  if (!S.loaded) { S.loaded = true; showApp(); }
  else { renderShell(); rerender(); }
  if (silent && S.tx.length > before) toast((S.tx.length - before) + ' transaksi baru disinkronisasi', 'Data diperbarui dari pengguna lain · baru saja', 'info', 3500);
  return true;
}
const cacheStateSoon = debounce(() => {
  try {
    const d = {
      me: S.me, settings: S.settings, categories: S.categories, products: S.products, variants: S.variants, bundles: S.bundles, bundleItems: S.bundleItems,
      userNames: S.userNames, users: S.users, stock: S.stock, stockTotals: S.stockTotals, tx: { cols: S.txCols, rows: S.tx.filter(t => !t._tmp).map(t => S.txCols.map(k => t[k])) },
      po: S.po, poItems: S.poItems, rts: S.rts, opname: S.opname, imports: S.imports, notifications: S.notifications, dashboard: S.dashboard, hasAiKey: S.hasAiKey, aiKeyMasked: S.aiKeyMasked
    };
    cacheState(d);
  } catch (e) { }
}, 1500);
function cacheState(d) {
  try { const s = JSON.stringify({ uid: d.me && d.me.id, at: Date.now(), ver: S.ver, data: d }); if (s.length < 3500000) store.set('rovelo_cache', JSON.parse(s)); } catch (e) { }
}
let _pollTimer = null;
function startPolling() {
  clearInterval(_pollTimer);
  _pollTimer = setInterval(ping, 45000);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) ping(); });
}
async function ping() {
  if (!S.token || document.hidden || Net.pending) return;
  const r = await callApi('app.ping');
  if (r.success && r.data && r.data.ver && S.loaded) { /* handleRes sudah menjadwalkan refresh jika versi berubah */ }
}

// ════════ 5. KOMPONEN UI ════════
function toast(title, msg, type, ms) {
  type = type || 'success';
  const icon = { success: 'check_circle', danger: 'error', warning: 'warning', info: 'sync' }[type] || 'info';
  const el = document.createElement('div');
  el.className = 'toast ' + type;
  el.setAttribute('role', type === 'danger' ? 'alert' : 'status');
  el.innerHTML = `<span class="tic">${I(icon)}</span><div class="tb"><b>${esc(title)}</b>${msg ? `<span>${esc(msg)}</span>` : ''}</div><button class="x" aria-label="Tutup">${I('close', 'sm')}</button>`;
  const kill = () => { el.classList.add('out'); setTimeout(() => el.remove(), 180); };
  $('.x', el).onclick = kill;
  $('#toasts').prepend(el);
  while ($('#toasts').children.length > 4) $('#toasts').lastChild.remove();
  setTimeout(kill, ms || (type === 'danger' ? 7000 : 4200));
}

// Modal konfirmasi (Promise<boolean>) — PRD 20.8
let _modalResolve = null;
function modal(o) {
  return new Promise(resolve => {
    closePop();
    _modalResolve = resolve;
    const box = $('#modalBox');
    box.className = 'modal-box ' + (o.size || '');
    const tone = o.tone || 'info';
    box.innerHTML = `
      ${o.title ? `<div class="mo-head">${o.icon ? `<span class="mo-ic ${tone}">${I(o.icon)}</span>` : ''}<div class="grow"><h3 id="moTitle">${esc(o.title)}</h3>${o.text ? `<p>${o.text}</p>` : ''}</div>${o.closeX ? `<button class="icon-btn" data-mo="cancel" aria-label="Tutup">${I('close')}</button>` : ''}</div>` : ''}
      ${o.body ? `<div class="mo-body">${o.body}</div>` : ''}
      ${o.noFoot ? '' : `<div class="mo-foot">${o.cancel === false ? '' : `<button class="btn" data-mo="cancel">${esc(o.cancel || 'Batal')}</button>`}${o.ok === false ? '' : `<button class="btn ${o.danger ? 'btn-danger' : 'btn-primary'}" data-mo="ok">${esc(o.ok || 'Ya, lanjutkan')}</button>`}</div>`}`;
    const m = $('#modal'); m.hidden = false; $('#scrim').hidden = false;
    requestAnimationFrame(() => { m.classList.add('show'); $('#scrim').classList.add('show'); });
    box.onclick = async e => {
      const b = e.target.closest('[data-mo]');
      if (!b) return;
      if (b.dataset.mo === 'ok') {
        if (o.onOk) { b.classList.add('loading'); const keep = await o.onOk(box); b.classList.remove('loading'); if (keep === false) return; }
        closeModal(true);
      } else closeModal(false);
    };
    if (o.onMount) o.onMount(box);
    setTimeout(() => { const f = $('input,select,textarea', box) || $('[data-mo="ok"]', box); if (f) f.focus(); }, 60);
  });
}
function closeModal(v) {
  const m = $('#modal');
  if (m.hidden) return;
  m.classList.remove('show');
  if ($('#drawer').hidden) $('#scrim').classList.remove('show');
  setTimeout(() => { m.hidden = true; if ($('#drawer').hidden) $('#scrim').hidden = true; }, 180);
  if (_modalResolve) { const r = _modalResolve; _modalResolve = null; r(!!v); }
}

// Drawer (form samping)
let _drawerClose = null;
function openDrawer(o) {
  closePop();
  const d = $('#drawer');
  d.className = 'drawer' + (o.wide ? ' wide' : '');
  d.innerHTML = `<div class="dr-head"><div class="grow"><div class="row gap-12"><h2 id="drTitle">${esc(o.title)}</h2>${o.badge || ''}</div>${o.sub ? `<p>${esc(o.sub)}</p>` : ''}</div><button class="icon-btn" data-act="drawer-close" aria-label="Tutup">${I('close')}</button></div>
    <div class="dr-body" id="drBody">${o.body || ''}</div>${o.foot ? `<div class="dr-foot" id="drFoot">${o.foot}</div>` : ''}`;
  d.hidden = false; $('#scrim').hidden = false;
  requestAnimationFrame(() => { d.classList.add('show'); $('#scrim').classList.add('show'); });
  _drawerClose = o.onClose || null;
  if (o.onMount) o.onMount(d);
  setTimeout(() => { const f = $('.dr-body input:not([type=checkbox]):not([type=radio]):not([readonly]), .dr-body select', d); if (f && !o.noFocus) f.focus(); }, 260);
}
function closeDrawer() {
  const d = $('#drawer');
  if (d.hidden) return;
  d.classList.remove('show'); $('#scrim').classList.remove('show');
  setTimeout(() => { d.hidden = true; d.innerHTML = ''; if ($('#modal').hidden) $('#scrim').hidden = true; }, 240);
  if (_drawerClose) { const f = _drawerClose; _drawerClose = null; f(); }
}

// Popover
function openPop(anchor, html, width) {
  const p = $('#pop');
  p.innerHTML = html; p.hidden = false; p.style.width = (width || 320) + 'px';
  const r = anchor.getBoundingClientRect();
  const w = Math.min(width || 320, window.innerWidth - 16);
  let left = Math.min(r.right - w, window.innerWidth - w - 8); left = Math.max(8, left);
  let top = r.bottom + 8;
  if (anchor.closest('.sidebar')) { left = Math.min(r.right + 8, window.innerWidth - w - 8); top = Math.max(8, r.bottom - p.offsetHeight); }
  p.style.left = left + 'px'; p.style.top = top + 'px'; p.style.width = w + 'px';
}
function closePop() { const p = $('#pop'); if (p && !p.hidden) { p.hidden = true; p.innerHTML = ''; } }

// Elemen kecil
function chCh(src) {
  const c = CHANNELS[src] || { color: '#6B7280', icon: 'storefront' };
  const lg = c.logo ? `<img src="${ASSETS[c.logo]}" alt="">` : I(c.icon || 'storefront');
  return `<span class="chip-ch"><span class="lg">${lg}</span>${esc(src || 'Manual')}</span>`;
}
function chLogo(src) {
  const c = CHANNELS[src] || { icon: 'storefront' };
  return `<span class="ch-logo">${c.logo ? `<img src="${ASSETS[c.logo]}" alt="${esc(src)}">` : I(c.icon || 'storefront')}</span>`;
}
function stPill(st) {
  if (st === 'out') return `<span class="pill pill-danger">${I('error', 'fill')}Habis</span>`;
  if (st === 'low') return `<span class="pill pill-warning">${I('warning', 'fill')}Low Stock</span>`;
  if (st === 'inactive') return `<span class="pill pill-outline">${I('block')}Nonaktif</span>`;
  return `<span class="pill pill-success">${I('check_circle', 'fill')}Normal</span>`;
}
function txPill(st, opt) {
  if (opt) return `<span class="pill pill-info">${I('sync')}Menyimpan</span>`;
  if (st === 'Pending') return `<span class="pill pill-info">${I('hourglass_top')}Pending</span>`;
  if (st === 'Confirmed') return `<span class="pill pill-success">${I('check_circle', 'fill')}Confirmed</span>`;
  return `<span class="pill pill-outline">${I('block')}Ditolak</span>`;
}
function colorHex(w) {
  const k = String(w || '').toLowerCase().trim();
  if (COLOR_HEX[k]) return COLOR_HEX[k];
  let h = 0; for (const ch of k) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return 'hsl(' + (h % 360) + ' 28% 45%)';
}
function isLightColor(w) { return /white|putih|cream|krem|khaki|beige|abu|grey|gray|sage|heather/i.test(w || ''); }
function dotC(w) { return `<span class="dot" style="background:${colorHex(w)}"></span>`; }
/** Thumbnail produk: foto (base64 kecil di sheet) atau kotak warna garmen. */
function thumb(vidOrSku, size) {
  const v = IX.v[vidOrSku];
  const p = v ? IX.p[v.SKU] : IX.p[vidOrSku];
  const cls = 'thumb' + (size ? ' ' + size : '');
  if (p && p.Thumb) return `<span class="${cls}"><img src="${esc(p.Thumb)}" alt="" loading="lazy"></span>`;
  const w = v ? v.Warna : (p ? (S.variants.find(x => x.SKU === p.SKU) || {}).Warna : '');
  const cat = p && IX.c[p.CategoryID] ? IX.c[p.CategoryID].NamaKategori : '';
  const ic = /kaos|kemeja|shirt|tee|jaket|hoodie|outer/i.test(cat + ' ' + (p ? p.NamaProduk : '')) ? 'apparel' : 'checkroom';
  return `<span class="${cls}${isLightColor(w) ? ' light' : ''}"><span class="sw" style="background:${colorHex(w)}"></span>${I(ic)}</span>`;
}
function prodCell(vid, extra) {
  return `<div class="prod">${thumb(vid)}<div class="col"><b class="ellipsis">${esc(vName(vid))}</b><span class="ellipsis">${esc(vSub(vid))}${extra ? ' · ' + extra : ''}</span></div></div>`;
}
function emptyHTML(icon, title, sub, action) {
  return `<div class="empty">${I(icon)}<b>${esc(title)}</b>${sub ? `<span>${esc(sub)}</span>` : ''}${action || ''}</div>`;
}
function noAccessHTML(what) {
  return `<div class="noaccess"><span class="ic">${I('lock')}</span><h2>Anda tidak punya akses</h2><p class="muted">Menu ${esc(what)} memerlukan izin khusus. Minta Owner menambahkan izin ini di General Settings → Member &amp; Hak Akses.</p><button class="btn" data-nav="dashboard">${I('arrow_back')}Kembali ke Dashboard</button></div>`;
}
function pageHead(title, opts) {
  opts = opts || {};
  return `<div class="ph"><div class="titles">${opts.over ? `<div class="overline" style="margin-bottom:6px">${esc(opts.over)}</div>` : ''}<div class="row"><h1>${esc(title)}</h1>${opts.badge || ''}</div>${opts.sub ? `<p class="sub">${opts.sub}</p>` : ''}</div><div class="actions">${opts.actions || ''}</div></div>`;
}
function kpi(o) {
  return `<div class="kpi ${o.cls || 'kpi-plain'}${o.act ? ' clickable' : ''}" ${o.act ? `data-act="${o.act}" ${o.arg ? `data-arg="${esc(o.arg)}"` : ''} role="button" tabindex="0"` : ''}>
    <div class="kpi-top"><span class="kpi-label">${esc(o.label)}</span><span class="kpi-ic">${I(o.icon)}</span></div>
    <div class="kpi-val">${o.val}${o.unit ? `<small>${esc(o.unit)}</small>` : ''}</div>
    ${o.sub ? `<div class="kpi-sub">${o.sub}</div>` : ''}</div>`;
}
function delta(curr, prev) {
  if (!prev) return curr ? `<span class="t-success">${I('trending_up', 'sm')} baru bulan ini</span>` : '<span class="muted">belum ada data</span>';
  const p = (curr - prev) / prev * 100;
  return `<span class="${p >= 0 ? 't-success' : 't-danger'}">${I(p >= 0 ? 'trending_up' : 'trending_down', 'sm')} ${p >= 0 ? '+' : ''}${fmt1(p)}%</span> <span class="muted">vs bulan lalu</span>`;
}
/** Paginasi tabel (25 baris per halaman agar DOM ringan). */
function paginate(list, key, size) {
  size = size || 25;
  const f = UI.f[key] || (UI.f[key] = {});
  const pages = Math.max(1, Math.ceil(list.length / size));
  f.pg = Math.min(Math.max(1, f.pg || 1), pages);
  return { rows: list.slice((f.pg - 1) * size, f.pg * size), page: f.pg, pages: pages, total: list.length, from: list.length ? (f.pg - 1) * size + 1 : 0, to: Math.min(f.pg * size, list.length) };
}
function pagerHTML(pg, key, noun) {
  const btn = (p, lbl, on, dis) => `<button data-act="page" data-key="${key}" data-pg="${p}" class="${on ? 'on' : ''}" ${dis ? 'disabled' : ''} aria-label="Halaman ${p}">${lbl}</button>`;
  let nums = [];
  for (let p = 1; p <= pg.pages; p++) if (p === 1 || p === pg.pages || Math.abs(p - pg.page) <= 1) nums.push(p); else if (nums[nums.length - 1] !== '…') nums.push('…');
  return `<div class="table-foot"><span>Menampilkan <b>${fmt(pg.from)}–${fmt(pg.to)}</b> dari <b>${fmt(pg.total)}</b> ${esc(noun)}</span>
    ${pg.pages > 1 ? `<div class="pager">${btn(pg.page - 1, I('chevron_left'), false, pg.page <= 1)}${nums.map(n => n === '…' ? '<span class="faint">…</span>' : btn(n, n, n === pg.page)).join('')}${btn(pg.page + 1, I('chevron_right'), false, pg.page >= pg.pages)}</div>` : ''}</div>`;
}

/** Combobox varian/bundle yang bisa dicari (keyboard: ↑ ↓ Enter Esc). */
function variantOptions(q, opts) {
  opts = opts || {};
  const qq = String(q || '').toLowerCase().split(/\s+/).filter(Boolean);
  const out = [];
  const list = opts.all ? S.variants : activeVariants();
  for (const v of list) {
    const p = IX.p[v.SKU];
    const hay = (v.VariantID + ' ' + (p ? p.NamaProduk : '') + ' ' + v.Warna + ' ' + v.Ukuran).toLowerCase();
    if (qq.every(t => hay.indexOf(t) >= 0)) {
      out.push({ id: v.VariantID, title: (p ? p.NamaProduk : v.SKU), sub: v.VariantID + ' · ' + v.Warna + ' · ' + v.Ukuran, end: 'Stok ' + fmt(stockOf(v.VariantID)), thumb: v.VariantID, kind: 'variant' });
      if (out.length > 60) break;
    }
  }
  if (opts.bundles) {
    S.bundles.filter(b => b.Aktif).forEach(b => {
      if (qq.every(t => (b.BundleSKU + ' ' + b.NamaBundle).toLowerCase().indexOf(t) >= 0)) out.unshift({ id: b.BundleSKU, title: b.NamaBundle, sub: b.BundleSKU + ' · paket', end: I('redeem', 'sm'), kind: 'bundle' });
    });
  }
  return out;
}
function comboHTML(id, value, placeholder, opts) {
  const label = value ? (opts && opts.bundle ? (IX.b[value] ? IX.b[value].NamaBundle + ' (' + value + ')' : value) : vLabel(value)) : '';
  return `<div class="combo" data-combo="${id}"><div class="input-icon">${I('search')}<input class="input" data-combo-input="${id}" value="${esc(label)}" placeholder="${esc(placeholder || 'Cari produk, SKU, warna, ukuran…')}" autocomplete="off" role="combobox" aria-expanded="false"><input type="hidden" data-combo-value="${id}" value="${esc(value || '')}"></div></div>`;
}
/** Mengaktifkan combobox di dalam root; onPick(item, el) dipanggil saat dipilih. */
function bindCombos(root, getOpts, onPick) {
  $$('[data-combo-input]', root).forEach(inp => {
    if (inp._bound) return;
    inp._bound = true;
    const id = inp.dataset.comboInput;
    const wrap = inp.closest('.combo');
    let list = null, items = [], hi = 0;
    const close = () => { if (list) { list.remove(); list = null; } inp.setAttribute('aria-expanded', 'false'); };
    const draw = () => {
      items = variantOptions(inp.value === inp.dataset.label ? '' : inp.value, getOpts ? getOpts(id, inp) : {});
      if (!list) { list = document.createElement('div'); list.className = 'combo-list'; wrap.appendChild(list); }
      inp.setAttribute('aria-expanded', 'true');
      hi = Math.min(hi, Math.max(0, items.length - 1));
      list.innerHTML = items.length ? items.map((it, i) => `<div class="combo-opt${i === hi ? ' on' : ''}" data-i="${i}">${it.kind === 'bundle' ? `<span class="thumb">${I('redeem')}</span>` : thumb(it.thumb)}<div class="col grow"><b class="ellipsis">${esc(it.title)}</b><span class="ellipsis">${esc(it.sub)}</span></div><span class="end muted">${it.end}</span></div>`).join('') : '<div class="combo-empty">Tidak ada yang cocok.</div>';
    };
    const pick = i => {
      const it = items[i]; if (!it) return;
      $(`[data-combo-value="${id}"]`, wrap).value = it.id;
      inp.value = it.kind === 'bundle' ? it.title + ' (' + it.id + ')' : vLabel(it.id);
      inp.dataset.label = inp.value;
      close();
      onPick && onPick(it, inp);
    };
    inp.addEventListener('focus', () => { inp.select(); draw(); });
    inp.addEventListener('input', () => { hi = 0; $(`[data-combo-value="${id}"]`, wrap).value = ''; draw(); });
    inp.addEventListener('keydown', e => {
      if (e.key === 'ArrowDown') { e.preventDefault(); hi = Math.min(hi + 1, items.length - 1); draw(); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); hi = Math.max(hi - 1, 0); draw(); }
      else if (e.key === 'Enter') { if (list) { e.preventDefault(); pick(hi); } }
      else if (e.key === 'Escape') close();
    });
    inp.addEventListener('blur', () => setTimeout(close, 160));
    wrap.addEventListener('mousedown', e => { const o = e.target.closest('.combo-opt'); if (o) { e.preventDefault(); pick(Number(o.dataset.i)); } });
  });
}

// ════════ 6. ROUTER SPA & KERANGKA ════════
const PAGES = {
  dashboard: { title: 'Dashboard', render: () => renderDashboard() },
  products: { title: 'Products', render: () => renderProducts() },
  stockin: { title: 'Stock In', render: () => renderStockIn() },
  stockout: { title: 'Stock Out', render: () => renderStockOut() },
  po: { title: 'Purchase Orders', render: () => renderPO() },
  rts: { title: 'Returns / RTS', render: () => renderRTS() },
  opname: { title: 'Stock Opname', perm: 'OPNAME', render: () => renderOpname() },
  history: { title: 'Audit / History', render: () => renderHistory() },
  settings: { title: 'General Settings', perm: ['SETTINGS', 'MEMBER_MANAGE'], render: () => renderSettings(), always: true }
};
/** Navigasi instan: sembunyikan/tampilkan section, tanpa server & tanpa ubah URL. */
function navigateTo(page, opts) {
  if (!PAGES[page]) page = 'dashboard';
  opts = opts || {};
  UI.page = page;
  if (opts.filter) UI.f[page] = Object.assign({}, UI.f[page] || {}, opts.filter, { pg: 1 });
  $$('.page').forEach(s => s.classList.toggle('active', s.id === 'page-' + page));
  $$('.nav-item').forEach(b => { b.classList.toggle('active', b.dataset.nav === page); b.setAttribute('aria-current', b.dataset.nav === page ? 'page' : 'false'); });
  document.title = PAGES[page].title + ' · ' + (S.settings.NamaBisnis || 'ROVELO') + ' Inventory';
  $('#sidebar').classList.remove('open');
  if (!$('#drawer').hidden && !opts.keepDrawer) closeDrawer();
  closePop();
  renderPage(page);
  store.set('rovelo_page', page);
  if (!opts.keepScroll) window.scrollTo(0, 0);
}
function renderPage(page) {
  const el = $('#page-' + page);
  const P = PAGES[page];
  if (P.perm && !can(P.perm) && !P.always) { el.innerHTML = noAccessHTML(P.title); return; }
  try { P.render(); } catch (e) { console.error(e); el.innerHTML = `<div class="banner banner-danger">${I('error')}<div><b>Halaman gagal dirender</b><p>${esc(e.message)}</p></div></div>`; }
}
/** Render ulang halaman aktif (ditunda jika pengguna sedang mengetik). */
function rerender() {
  if (!S.loaded) return;
  const a = document.activeElement;
  if (a && $('#page-' + UI.page).contains(a) && /INPUT|TEXTAREA|SELECT/.test(a.tagName) && a.type !== 'checkbox' && a.type !== 'radio') { UI.deferred = true; return; }
  UI.deferred = false;
  const y = window.scrollY;
  renderPage(UI.page);
  window.scrollTo(0, y);
}
function logoSrc(light) {
  const custom = S.settings && S.settings.LogoData || (window.__PUBLIC__ && window.__PUBLIC__.logo);
  if (custom) return custom;
  return light ? ASSETS.logoLight : ASSETS.logoDark;
}
function renderLogos() {
  const custom = !!(S.settings && S.settings.LogoData || (window.__PUBLIC__ && window.__PUBLIC__.logo));
  $$('.js-logo-light').forEach(i => { i.src = logoSrc(true); i.classList.toggle('custom', custom); });
  $$('.js-logo-dark').forEach(i => { i.src = logoSrc(false); });
  const dark = document.documentElement.getAttribute('data-theme') === 'dark';
  const b = $('#bootLogo'); if (b) { b.src = logoSrc(dark); b.style.filter = custom && dark ? 'brightness(0) invert(1)' : ''; }
}
function renderShell() {
  if (!S.me) return;
  renderLogos();
  $('#sideAvatar').textContent = initials(S.me.nama);
  $('#sideName').textContent = S.me.nama;
  $('#sideRole').textContent = S.me.role + ' · @' + S.me.username;
  const h = wib(now()).getUTCHours();
  const salam = h < 11 ? 'Selamat pagi' : h < 15 ? 'Selamat siang' : h < 18 ? 'Selamat sore' : 'Selamat malam';
  $('#greet').innerHTML = `${salam}, <b>${esc(S.me.nama.split(' ')[0])}</b> · Ringkasan stok hari ini`;
  $('#todayPill').textContent = fmtDayLong(now());
  // Lencana menu
  const g = Object.values(groups());
  const pendIn = g.filter(x => x.status === 'Pending' && (x.jenis === 'IN' || x.jenis === 'PO_IN')).length;
  const pendOut = g.filter(x => x.status === 'Pending' && (x.jenis === 'OUT' || x.jenis === 'BUNDLE_OUT')).length;
  const rtsP = S.rts.filter(r => r.Status === 'PENDING_STOCK').length;
  const late = poLate().length;
  const badge = { stockin: pendIn, stockout: pendOut, rts: rtsP, po: late };
  $$('.nav-item').forEach(b => {
    const k = b.dataset.nav;
    $$('.badge-dot,.lock', b).forEach(x => x.remove());
    const P = PAGES[k];
    if (P.perm && !can(P.perm)) b.insertAdjacentHTML('beforeend', I('lock', 'lock'));
    else if (badge[k]) b.insertAdjacentHTML('beforeend', `<span class="badge-dot${k === 'po' ? ' alert' : ''}" title="${k === 'po' ? 'PO terlambat' : 'Menunggu tindakan'}">${badge[k]}</span>`);
  });
  const n = notifList().filter(x => !x.read).length;
  const c = $('#notifCount'); c.hidden = !n; c.textContent = n > 9 ? '9+' : n;
  $('#themeIcon').textContent = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light_mode' : 'dark_mode';
}
function poLate() { return S.po.filter(p => (p.Status === 'Ordered' || p.Status === 'Partially Received') && p.TanggalTarget && dayIdx(p.TanggalTarget) < dayIdx(now())); }

// ── Notifikasi (diturunkan dari data + tersimpan) ──
function notifList() {
  const out = [];
  const low = S.variants.filter(v => v.Aktif && vStatus(v) === 'low'), oos = S.variants.filter(v => v.Aktif && vStatus(v) === 'out');
  const readKey = k => !!(UI.readNotif[k] || (store.get('rovelo_nread_' + (S.me && S.me.id)) || {})[k]);
  if (oos.length) { const k = 'oos:' + oos.map(v => v.VariantID).join(','); out.push({ key: k, icon: 'error', tone: 'danger', title: oos.length + ' varian habis (Out of Stock)', text: oos.slice(0, 3).map(v => v.VariantID).join(', ') + (oos.length > 3 ? '…' : ''), go: ['products', { status: 'out' }], read: readKey(k) }); }
  if (low.length) { const k = 'low:' + low.map(v => v.VariantID).join(','); out.push({ key: k, icon: 'warning', tone: 'warning', title: low.length + ' varian Low Stock', text: 'Stok di bawah batas minimum — perlu restock.', go: ['products', { status: 'low' }], read: readKey(k) }); }
  poLate().forEach(p => { const k = 'po:' + p.PONumber + ':' + p.Status; out.push({ key: k, icon: 'schedule', tone: 'danger', title: p.PONumber + ' melewati target', text: (p.Vendor || 'PO') + ' · target ' + fmtDate(p.TanggalTarget), go: ['po', { sel: p.PONumber }], read: readKey(k) }); });
  const lim = Number(S.settings.RTSPendingHari || 7);
  const rtsOld = S.rts.filter(r => r.Status === 'PENDING_STOCK' && dayIdx(now()) - dayIdx(r.TanggalRetur || r.DibuatPada) > lim);
  if (rtsOld.length) { const k = 'rts:' + rtsOld.map(r => r.RTSID).join(','); out.push({ key: k, icon: 'assignment_return', tone: 'warning', title: rtsOld.length + ' RTS pending lebih dari ' + lim + ' hari', text: 'Periksa kondisi barang dan proses ke stok.', go: ['rts', { tab: 'PENDING_STOCK', old: true }], read: readKey(k) }); }
  S.imports.filter(i => i.Status === 'Preview').forEach(i => { const k = 'imp:' + i.ImportID; out.push({ key: k, icon: 'upload_file', tone: 'info', title: 'Import menunggu konfirmasi', text: i.NamaFile + ' · ' + i.Sumber + ' · ' + fmt(i.BarisValid) + ' baris', go: ['stockout', { tab: 'imports' }], read: readKey(k) }); });
  S.notifications.forEach(n => out.push({ key: 'n:' + n.id, id: n.id, icon: n.jenis === 'Backup Gagal' ? 'cloud_off' : n.jenis === 'Stok Minus' ? 'remove_circle' : 'info', tone: /Gagal|Minus/.test(n.jenis) ? 'danger' : 'info', title: n.jenis, text: n.pesan, time: n.tanggal, read: n.read }));
  return out;
}
function openNotif(btn) {
  const list = notifList();
  const tone = t => `background:var(--${t}-bg);color:var(--${t === 'danger' ? 'danger' : t})`;
  openPop(btn, `<div class="pop-head"><b>Notifikasi</b>${list.some(x => !x.read) ? `<button class="link" data-act="notif-readall" style="font-size:12.5px">Tandai semua dibaca</button>` : ''}</div>
    <div class="pop-list">${list.length ? list.map((n, i) => `<button class="pop-item${n.read ? '' : ' unread'}" data-act="notif-go" data-i="${i}"><span class="nic" style="${tone(n.tone)}">${I(n.icon, 'sm')}</span><div class="grow"><b>${esc(n.title)}</b><span>${esc(n.text)}</span>${n.time ? `<span class="faint">${relTime(n.time)}</span>` : ''}</div></button>`).join('') : emptyHTML('notifications_off', 'Tidak ada notifikasi', 'Semua aman untuk saat ini.')}</div>`, 380);
  UI._notifCache = list;
}
function markNotifRead(items) {
  const key = 'rovelo_nread_' + S.me.id;
  const m = store.get(key) || {};
  const ids = [];
  items.forEach(n => { UI.readNotif[n.key] = 1; m[n.key] = 1; if (n.id) { ids.push(n.id); const sn = S.notifications.find(x => x.id === n.id); if (sn) sn.read = true; } });
  store.set(key, m);
  if (ids.length) callApi('notif.read', { ids: ids });
  renderShell();
}
function openUserMenu(btn) {
  const dark = document.documentElement.getAttribute('data-theme') === 'dark';
  openPop(btn, `<div class="pop-head"><div class="row gap-12"><span class="avatar">${esc(initials(S.me.nama))}</span><div class="col"><b>${esc(S.me.nama)}</b><span class="muted" style="font-size:12.5px">${esc(S.me.role)} · @${esc(S.me.username)}</span></div></div></div>
    <button class="menu-item" data-act="change-pass">${I('key')}Ubah kata sandi</button>
    <button class="menu-item" data-act="theme">${I(dark ? 'light_mode' : 'dark_mode')}${dark ? 'Mode terang' : 'Mode gelap'}</button>
    <button class="menu-item" data-act="logout-all">${I('devices')}Keluar dari perangkat lain</button>
    <button class="menu-item danger" data-act="logout">${I('logout')}Keluar</button>`, 270);
}
function toggleTheme() {
  const dark = document.documentElement.getAttribute('data-theme') !== 'dark';
  document.documentElement.setAttribute('data-theme', dark ? 'dark' : 'light');
  store.set('rovelo_theme', dark ? 'dark' : 'light');
  closePop(); renderShell(); renderLogos();
  if (UI.page === 'dashboard') rerender();
}

// ════════ 7. LOGIN & SESI ════════
function showLogin(msg) {
  $('#boot').hidden = true; $('#app').hidden = true; $('#auth').hidden = false;
  $('#loginForm').hidden = false; $('#recoverForm').hidden = true;
  $('#authChannels').innerHTML = ['shopee', 'tiktok', 'lazada'].map(k => `<img src="${ASSETS[k]}" alt="">`).join('');
  renderAuthFoot();
  renderLogos();
  if (msg) showFormErr('#lgErr', msg);
  setTimeout(() => $('#lgUser').focus(), 50);
}
function renderAuthFoot() {
  const p = window.__PUBLIC__ || {};
  $('#authFoot').textContent = (p.name || 'ROVELO') + ' Inventory Management System · v' + (p.version || '1.1');
}
function showFormErr(sel, msg) { const b = $(sel); b.hidden = !msg; if (msg) $('p', b).textContent = msg; }
function showApp() {
  $('#auth').hidden = true; $('#app').hidden = false;
  const b = $('#boot'); b.style.opacity = '0'; setTimeout(() => { b.hidden = true; }, 250);
  renderShell();
  const last = store.get('rovelo_page');
  navigateTo(PAGES[last] ? last : 'dashboard');
  startPolling();
}
function showBootError(msg) {
  $('#boot').hidden = false;
  $('#boot').innerHTML = `<div class="boot-inner" style="max-width:420px;text-align:center"><span class="ms xl">cloud_off</span><h2>Tidak dapat memuat data</h2><p class="muted">${esc(msg)}</p><button class="btn btn-primary" data-act="reload-app">${I('refresh')}Coba lagi</button></div>`;
}
async function doLogin(e) {
  e.preventDefault();
  const u = $('#lgUser').value.trim(), p = $('#lgPass').value;
  if (!u || !p) { showFormErr('#lgErr', 'Isi username dan kata sandi.'); return; }
  const btn = $('#lgBtn'); btn.classList.add('loading'); showFormErr('#lgErr', '');
  const r = await callApi('auth.login', { username: u, password: p });
  btn.classList.remove('loading');
  if (!r.success) { showFormErr('#lgErr', r.message); $('#lgPass').select(); return; }
  S.token = r.data.token; S.me = r.data.me; store.set('rovelo_token', S.token);
  $('#lgPass').value = '';
  $('#auth').hidden = true;
  $('#boot').hidden = false; $('#boot').style.opacity = '1';
  const ok = await refresh(false);
  if (ok) toast(r.message, 'Data stok terbaru sudah dimuat.', 'success');
}
async function doRecover(e) {
  e.preventDefault();
  const btn = $('#rcBtn'); btn.classList.add('loading'); showFormErr('#rcErr', '');
  const r = await callApi('auth.recover', { username: $('#rcUser').value.trim(), code: $('#rcCode').value.trim(), newPassword: $('#rcPass').value });
  btn.classList.remove('loading');
  if (!r.success) { showFormErr('#rcErr', r.message); return; }
  $('#recoverForm').reset();
  showLogin();
  toast('Sandi berhasil diganti', 'Sisa kode pemulihan: ' + r.data.left + '. Silakan masuk.', 'success', 7000);
}
function resetState() {
  S.token = null; S.me = null; S.loaded = false; S.tx = []; S.ver = null; UI.f = {}; UI.imp = null; UI.op = null; UI.backups = null; UI.hist = null; UI.histKey = null; UI.log = null; UI.logKey = null;
  $$('.page').forEach(p => { p.innerHTML = ''; });
  Object.keys(CH).forEach(k => { try { CH[k].destroy(); } catch (e) { } delete CH[k]; });
  clearInterval(_pollTimer);
}
function forceLogout(msg) {
  store.del('rovelo_token'); store.del('rovelo_cache');
  resetState(); closeDrawer(); closeModal(false); closePop();
  showLogin(msg || 'Sesi berakhir. Silakan masuk kembali.');
}
async function logout() {
  const ok = await modal({ icon: 'logout', title: 'Keluar dari aplikasi?', text: 'Data lokal di perangkat ini akan dibersihkan.', ok: 'Keluar' });
  if (!ok) return;
  store.del('rovelo_token'); store.del('rovelo_cache');
  resetState(); showLogin();
}
function changePassword() {
  closePop();
  modal({
    icon: 'key', title: 'Ubah kata sandi', text: 'Sesi di perangkat lain akan diakhiri.', ok: 'Simpan sandi', body: `<div class="col gap-12">
      <div class="field"><label for="cpOld">Sandi lama</label><input id="cpOld" type="password" class="input" autocomplete="current-password"></div>
      <div class="field"><label for="cpNew">Sandi baru</label><input id="cpNew" type="password" class="input" autocomplete="new-password"><span class="help">Minimal 8 karakter, huruf dan angka.</span></div>
      <div class="field"><label for="cpNew2">Ulangi sandi baru</label><input id="cpNew2" type="password" class="input" autocomplete="new-password"></div>
      <div id="cpErr" class="banner banner-danger" hidden>${I('error')}<p></p></div></div>`,
    onOk: async box => {
      const o = $('#cpOld', box).value, n = $('#cpNew', box).value, n2 = $('#cpNew2', box).value;
      if (n !== n2) { showFormErr('#cpErr', 'Sandi baru tidak sama.'); return false; }
      const r = await callApi('auth.changePassword', { oldPassword: o, newPassword: n });
      if (!r.success) { showFormErr('#cpErr', r.message); return false; }
      S.token = r.data.token; store.set('rovelo_token', S.token);
      toast('Sandi diganti', r.message, 'success');
    }
  });
}

// ════════ 8. EVENT GLOBAL (delegasi) ════════
const ACT = {}; // diisi oleh modul halaman: ACT['nama-aksi'] = (el, ev) => …
Object.assign(ACT, {
  'drawer-close': () => closeDrawer(),
  'toggle-sidebar': () => $('#sidebar').classList.toggle('open'),
  'notif': el => { if (!$('#pop').hidden) { closePop(); return; } openNotif(el); },
  'notif-go': el => { const n = UI._notifCache[Number(el.dataset.i)]; if (!n) return; markNotifRead([n]); closePop(); if (n.go) navigateTo(n.go[0], { filter: n.go[1] }); },
  'notif-readall': () => { markNotifRead(notifList()); closePop(); },
  'user-menu': el => { if (!$('#pop').hidden) { closePop(); return; } openUserMenu(el); },
  'theme': () => toggleTheme(),
  'logout': () => { closePop(); logout(); },
  'logout-all': async () => { closePop(); const r = await callApi('auth.logoutAll'); if (r.success) { S.token = r.data.token; store.set('rovelo_token', S.token); toast('Selesai', r.message, 'success'); } else toast('Gagal', r.message, 'danger'); },
  'change-pass': () => changePassword(),
  'pw-toggle': el => { const i = $('#' + el.dataset.for); i.type = i.type === 'password' ? 'text' : 'password'; $('.ms', el).textContent = i.type === 'password' ? 'visibility' : 'visibility_off'; },
  'show-recover': () => { $('#loginForm').hidden = true; $('#recoverForm').hidden = false; $('#rcUser').value = $('#lgUser').value; $('#rcUser').focus(); },
  'show-login': () => { $('#recoverForm').hidden = true; $('#loginForm').hidden = false; },
  'page': el => { const f = UI.f[el.dataset.key] || (UI.f[el.dataset.key] = {}); f.pg = Number(el.dataset.pg); rerender(); },
  'reload-app': () => { $('#boot').innerHTML = '<div class="boot-inner"><img id="bootLogo" alt="ROVELO"><div class="bar-loader"></div></div>'; renderLogos(); location.reload(); }
});
document.addEventListener('click', e => {
  const nav = e.target.closest('[data-nav]');
  if (nav) { e.preventDefault(); navigateTo(nav.dataset.nav, nav.dataset.filter ? { filter: JSON.parse(nav.dataset.filter) } : {}); return; }
  const a = e.target.closest('[data-act]');
  if (a && ACT[a.dataset.act]) { if (a.tagName === 'A') e.preventDefault(); ACT[a.dataset.act](a, e); return; }
  if (!$('#pop').hidden && !e.target.closest('#pop')) closePop();
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') { if (!$('#pop').hidden) closePop(); else if (!$('#modal').hidden) closeModal(false); else if (!$('#drawer').hidden) closeDrawer(); }
  if ((e.key === 'Enter' || e.key === ' ') && e.target.matches('.kpi.clickable')) { e.preventDefault(); e.target.click(); }
});
document.addEventListener('focusout', () => { setTimeout(() => { if (UI.deferred && !(document.activeElement && /INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))) rerender(); }, 120); });
window.addEventListener('resize', debounce(closePop, 100));

// ════════ 9. INISIALISASI ════════
function init() {
  $('#scrim').addEventListener('click', () => { if (!$('#modal').hidden) closeModal(false); else closeDrawer(); });
  $('#loginForm').addEventListener('submit', doLogin);
  $('#recoverForm').addEventListener('submit', doRecover);
  loadScript(CDN.chart).catch(() => { });
  if (!apiUrlValid()) { showBootError('Alamat backend belum diatur. Buka file js/config.js, isi GAS_URL dengan URL Web App Apps Script (berakhiran /exec), lalu upload ulang ke GitHub.'); return; }
  // Info publik: tampil instan dari cache lokal, lalu diperbarui di latar
  window.__PUBLIC__ = store.get('rovelo_pub') || null;
  renderLogos();
  const NOT_READY = 'Database belum disiapkan. Jalankan setupAppEnvironment() dari editor Apps Script, lalu deploy versi baru.';
  const pubReq = loadPublic().then(p => {
    window.__PUBLIC__ = p; store.set('rovelo_pub', p);
    renderLogos(); if (!$('#auth').hidden) renderAuthFoot();
    if (p.ready === false && !S.loaded) showBootError(NOT_READY);
    return p;
  }).catch(err => { console.warn('Info publik gagal dimuat:', err); return null; });
  const token = store.get('rovelo_token') || window.__DEMO_TOKEN__;
  if (!token) {
    if (window.__PUBLIC__ && window.__PUBLIC__.ready !== false) { showLogin(); return; }
    pubReq.then(p => {
      if (!p) showBootError('Server tidak dapat dihubungi. Periksa koneksi internet. Jika masalah berlanjut, pastikan GAS_URL di js/config.js benar dan deployment Apps Script diatur "Who has access: Anyone".');
      else if (p.ready !== false) showLogin();
    });
    return;
  }
  S.token = token;
  const cache = store.get('rovelo_cache');
  if (cache && cache.data && cache.data.me) {
    // Tampil instan dari cache lokal, lalu segarkan di latar (Prinsip 2).
    try { applyBoot(cache.data); S.ver = cache.ver; S.loaded = true; showApp(); } catch (e) { S.loaded = false; }
    refresh(true);
  } else refresh(false);
}
// (init dipicu di akhir file JavaScript — setelah semua modul halaman terdefinisi)
